cssInjection:
.markdown-body .ext-card{border-radius:10px;padding:.65em 1em;margin:.9em 0;break-inside:avoid;background:var(--doc-surface);border:1px solid var(--doc-line);border-left:4px solid var(--doc-accent)}
.markdown-body .ext-card-h{font-weight:700;margin-bottom:.3em;color:var(--doc-accent)}
.markdown-body .ext-card.ext-warn{border-left-color:#d64545}
.markdown-body .ext-card.ext-warn .ext-card-h{color:#b91c1c}
.markdown-body .ext-card.ext-ans{border-left-color:#16a34a}
.markdown-body .ext-card.ext-ans .ext-card-h{color:#15803d}
.markdown-body .ext-card > :last-child{margin-bottom:0}
.markdown-body .ext-card p{margin:.35em 0}
.markdown-body .ext-tag{display:inline-block;padding:0 .4em;margin:0 .1em;border-radius:4px;background:var(--doc-quote);color:var(--doc-accent);font-size:.92em;font-weight:600;border:1px solid var(--doc-line)}
.markdown-body .ext-warn{color:#b91c1c}
